@startuml

class School {
  + name : string
}

class Teacher {
  + firstName : string
  + lastName : string
  + email : string
}

class Student {
  + firstName : string
  + lastName : string
}

class TeachingRelationship {
  + hours : int
}

class Room {
  + name : string
}

class Classroom extends Room {
  + capacity : int
}

class Gym extends Room {
  + size : float
}

class ClassGroup {
  + name : string
}

School "1" -- "1" Teacher : principal
School "1" -- "1..*" Teacher : employs
Teacher "1" -- "0..3" School : teaches
Teacher "1" -- "0..*" TeachingRelationship
School "0..*" -- "0..*" Teacher : TeachingRelationship

Student "1" -- "1" ClassGroup : belongs to
ClassGroup "1" -- "1" Classroom : assigned to
ClassGroup "10..31" -- "1" Student : contains

@enduml

